module femtoPLL #(
    parameter freq = 40
) (
    input  wire pclk,
    output wire clk
);

    SB_PLL40_CORE pll (
        .REFERENCECLK (pclk),
        .PLLOUTCORE   (clk),
        .RESETB       (1'b1),
        .BYPASS       (1'b0)
    );

    defparam pll.FEEDBACK_PATH = "SIMPLE";
    defparam pll.PLLOUT_SELECT = "GENCLK";

    generate
        case (freq)

            12: begin
                defparam pll.DIVR         = 4'b0000;
                defparam pll.DIVF         = 7'b0000000;
                defparam pll.DIVQ         = 3'b000;
                defparam pll.FILTER_RANGE = 3'b001;
            end

            16: begin
