                defparam pll.DIVQ         = 3'b101;
                defparam pll.FILTER_RANGE = 3'b001;
            end

            24: begin
                defparam pll.DIVR         = 4'b0000;
                defparam pll.DIVF         = 7'b0111111;
                defparam pll.DIVQ         = 3'b101;
                defparam pll.FILTER_RANGE = 3'b001;
            end

            25: begin
